import {parse} from 'acorn';
import {readFile,mkdir,writeFile,copyFile} from 'node:fs/promises';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {fileURLToPath} from 'node:url';
const root=fileURLToPath(new URL('../',import.meta.url)), target=path.join(root,'plugins/drawai');
const read=name=>readFile(path.join(root,'scripts/upstream/drawai',name.replaceAll('/','-')+'.txt'),'utf8');
const hash=s=>createHash('sha256').update(s).digest('hex');
const check=process.argv.includes('--check'), records=[];
async function emit(name,source){const p=path.join(target,name);records.push({path:name,sha256:hash(source)});if(check){if(await readFile(p,'utf8')!==source)throw Error('Vendored source drift: '+name);}else{await mkdir(path.dirname(p),{recursive:true});await writeFile(p,source);}}
function walk(n,visit,parent,key){if(!n||typeof n!=='object')return;visit(n,parent,key);for(const [k,v]of Object.entries(n)){if(k==='start'||k==='end')continue;if(Array.isArray(v))for(const x of v)walk(x,visit,n,k);else if(v&&typeof v==='object')walk(v,visit,n,k);}}
