const style=await read('src/style-kernel.js');
await emit('upstream/style-kernel.mjs',style);
let mx=await read('src/mxfile.js');
mx=mx.replace("'./style-kernel.js'","'./style-kernel.mjs'").replace('inflateRawSync(buffer)','inflateRawSync(buffer, { maxOutputLength: 16 * 1024 * 1024 })').replace('inflateSync(buffer)','inflateSync(buffer, { maxOutputLength: 16 * 1024 * 1024 })');
mx=mx.replace(".digest('hex').slice(0, 12)",".digest('hex')");
await emit('upstream/mxfile.mjs',mx);
const clientRoots=['buildGeometry','routeEdgeStyled','pathOf','computeAlignMoves','marqueeHits','dragMoveOf','draggedGeometry','hitNodeAt','resizeBox','computeFitView','zoomViewAt','hiddenLayerIds','isHiddenCell','layerIsLocked','filterEditableIds','nodeBoxOf','wrapLabel','edgeLabelPosition','snapTo','GRID','EDGE_GRID','alignGuidesFor','boxOfBoxes'];
await emit('upstream/geometry.mjs',extract(await read('src/client.js'),clientRoots,"import * as styleKernel from './style-kernel.mjs';"));
let host=await read('src/index.js');
const tree=parse(host,{ecmaVersion:'latest',sourceType:'module'});
const apply=tree.body.find(n=>n.type==='FunctionDeclaration'&&n.id.name==='applyOps');
const loop=apply.body.body.find(n=>n.type==='ForStatement');
const allowed=new Set(['addNode','addEdge','duplicate','move','order','setEdge','setLabelPos','addLayer','setLayer','setLayerProps','setLabel','setStyle','remove']);
const removed=[];
for(const n of loop.body.body){if(n.type!=='IfStatement')continue;const kinds=[];walk(n.test,x=>{if(x.type==='Literal'&&typeof x.value==='string')kinds.push(x.value)});if(kinds.length&&kinds.some(k=>!allowed.has(k))&&kinds.every(k=>k!=='object'))removed.push(n);}
