// Remove media-only branches before dependency analysis, rather than providing
// fake DSH/media services to code that the first version cannot use.
const edits=[];
walk(parse(host,{ecmaVersion:'latest',sourceType:'module'}),n=>{
 if(n.type==='IfStatement'&&!n.alternate){const test=host.slice(n.test.start,n.test.end);if(test==='videoNode'||/op\.shape === '(video|svg)'|has\(op, 'svg'\)/.test(test))edits.push({start:n.start,end:n.end,text:''});}
 if(n.type==='ConditionalExpression'&&n.test.type==='Identifier'&&['videoNode','svgNode'].includes(n.test.name))edits.push({start:n.start,end:n.end,text:host.slice(n.alternate.start,n.alternate.end)});
});
const outer=edits.filter(a=>!edits.some(b=>b!==a&&b.start<=a.start&&b.end>=a.end));
for(const e of outer.sort((a,b)=>b.start-a.start))host=host.slice(0,e.start)+e.text+host.slice(e.end);
host=host.replace(/videoNode \? DEFAULT_VIDEO_W : /g,'').replace(/videoNode \? DEFAULT_VIDEO_H : /g,'').replace(/svgNode \? DEFAULT_SVG_W : /g,'').replace(/svgNode \? DEFAULT_SVG_H : /g,'');
host=host.replace('hasX === false && hasY === false && dx === 0 && dy === 0','hasX === false && hasY === false && dx === 0 && dy === 0 && !has(op, \'w\') && !has(op, \'h\')');
host=host.replace('n.y = Math.round(hasY ? Number(op.y) : numberOr(n.y, 0) + dy)',"n.y = Math.round(hasY ? Number(op.y) : numberOr(n.y, 0) + dy)\n          if (has(op, 'w')) n.w = Number(op.w)\n          if (has(op, 'h')) n.h = Number(op.h)");
const styleImports=tree.body.filter(n=>n.type==='ImportDeclaration'&&n.source.value==='./style-kernel.js').flatMap(n=>n.specifiers.map(x=>x.imported.name));
await emit('upstream/operations.mjs',extract(host,['applyOps'], 'import { '+styleImports.join(', ')+" } from './style-kernel.mjs';"));
