const vendors=[['saxes/saxes.js','vendor/saxes.cjs'],['xmlchars/xml/1.0/ed5.js','vendor/xmlchars/xml/1.0/ed5.cjs'],['xmlchars/xml/1.1/ed2.js','vendor/xmlchars/xml/1.1/ed2.cjs'],['xmlchars/xmlns/1.0/ed3.js','vendor/xmlchars/xmlns/1.0/ed3.cjs'],['xmlchars/LICENSE','vendor/xmlchars-LICENSE.txt']];
for(const [src,dst]of vendors){let s=await readFile(path.join(root,'node_modules',src),'utf8');if(src.startsWith('saxes/'))s=s.replaceAll('require("xmlchars/xml/1.0/ed5")','require("./xmlchars/xml/1.0/ed5.cjs")').replaceAll('require("xmlchars/xml/1.1/ed2")','require("./xmlchars/xml/1.1/ed2.cjs")').replaceAll('require("xmlchars/xmlns/1.0/ed3")','require("./xmlchars/xmlns/1.0/ed3.cjs")').replace(/\/\/# sourceMappingURL=.*$/m,'');await emit(dst,s);}
