await emit('upstream/SOURCES.json',JSON.stringify({repository:'https://github.com/fourzkw/dsh-drawai',commit:'80eb15e0a3a11cb4c88cf8716382d03cdf0e5b03',changes:['ES module suffixes','Bounded zlib inflation','Extract dependency closures of geometry and supported operations; exclude DSH/media APIs'],generated:records},null,2)+'\n');
